const KEEPALIVE_MS = 20_000;

export function setupServiceWorker(wid: string, base: string, keepAliveMs = KEEPALIVE_MS): void {
  if (!("serviceWorker" in navigator)) {
    return;
  }
  if (document.documentElement.dataset.pathlandServiceWorker == null) {
    void navigator.serviceWorker
      .getRegistrations()
      .then((regs) => Promise.all(regs.map((reg) => reg.unregister())))
      .catch((err) => log.debug("sw", `unregister failed: ${err}`));
    return;
  }

  let registration: ServiceWorkerRegistration | undefined;
  let keepAliveTimer: ReturnType<typeof window.setInterval> | undefined;
  let closing = false;

  // The controller can be momentarily null right after `register` (and on the first
  // install), so always resolve the target lazily.
  const target = (): ServiceWorker | null =>
    navigator.serviceWorker.controller ?? registration?.active ?? null;

  const postWid = (): void => {
    target()?.postMessage({ type: "pathland-wid", wid });
  };

  const ping = (): void => {
    target()?.postMessage({ type: "pathland-keepalive" });
  };

  const startKeepAlive = (): void => {
    if (keepAliveTimer !== undefined) return;
    keepAliveTimer = window.setInterval(ping, keepAliveMs);
  };

  const stopKeepAlive = (): void => {
    if (keepAliveTimer === undefined) return;
    window.clearInterval(keepAliveTimer);
    keepAliveTimer = undefined;
  };

  void navigator.serviceWorker
    .register(`${base}/sw.js`, { scope: "/" })
    .then((reg) => {
      registration = reg;
      const seed = (): void => {
        postWid();
        startKeepAlive();
      };
      // Seed now, and again whenever the worker/controller becomes available: `reg.active`
      // and `controller` can be momentarily null right after `register` (and on the first
      // install), so a single post can be missed — the worker would then have no id for
      // this tab and the SSR would render defaults on the next navigation.
      seed();
      reg.addEventListener?.("updatefound", seed);
      void navigator.serviceWorker.ready.then(seed);
      navigator.serviceWorker.addEventListener?.("controllerchange", seed);
    })
    // Surfaced (not swallowed): a failed registration is otherwise invisible — e.g. a
    // missing Service-Worker-Allowed header, which the browser reports only in its console.
    .catch((err) => log.warn("sw", `service worker registration failed: ${err}`));

  // Keep the worker warm while this tab is open. Browsers terminate an idle service
  // worker after ~30 s; a cold worker delays the next navigation by its boot time.
  // The worker ignores this message; receiving it is what resets the idle timer.
  window.addEventListener("focus", ping);
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") ping();
